#!/usr/bin/env bash
# Formats and table functions of the 26.3 Decimal512 port that the 26.8 port had lost (restored in round 5): MsgPack
# Decimal512 (bin 8 of 64 bytes), CapnProto and Protobuf serializers with autogenerated schemas for (U)Int512 and
# Decimal512, generateRandom for Decimal512. Round trips: the value read back is the value written. Files get unique names
# and are removed. (PostgreSQL/MySQL engines and the PostgreSQL wire protocol need external servers: not covered here.)

CURDIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
# shellcheck source=../shell_config.sh
. "$CURDIR"/../shell_config.sh

F="${CLICKHOUSE_TEST_UNIQUE_NAME}"
S="x Int512, y UInt512, d Decimal(154, 3)"
V="toInt512('-12345678901234567890123456789012345678901234567890123456789012345678901234567890'), bitShiftLeft(toUInt512(1), 511), toDecimal512('-1.5', 3)"

echo "-- msgpack decimal512"
$CLICKHOUSE_CLIENT --query="INSERT INTO FUNCTION file('${F}.msgpack', 'MsgPack', 'd Decimal(154, 3)') SETTINGS engine_file_truncate_on_insert = 1 SELECT toDecimal512('-1.5', 3)"
$CLICKHOUSE_CLIENT --query="SELECT d, toTypeName(d) FROM file('${F}.msgpack', 'MsgPack', 'd Decimal(154, 3)')"

echo "-- capnproto with the autogenerated schema"
$CLICKHOUSE_CLIENT --query="INSERT INTO FUNCTION file('${F}.capnp', 'CapnProto', '$S') SETTINGS engine_file_truncate_on_insert = 1, format_capn_proto_use_autogenerated_schema = 1 SELECT $V"
$CLICKHOUSE_CLIENT --query="SELECT * FROM file('${F}.capnp', 'CapnProto', '$S') SETTINGS format_capn_proto_use_autogenerated_schema = 1"

echo "-- protobuf with the autogenerated schema"
$CLICKHOUSE_CLIENT --query="INSERT INTO FUNCTION file('${F}.pb', 'Protobuf', '$S') SETTINGS engine_file_truncate_on_insert = 1, format_protobuf_use_autogenerated_schema = 1 SELECT $V"
$CLICKHOUSE_CLIENT --query="SELECT * FROM file('${F}.pb', 'Protobuf', '$S') SETTINGS format_protobuf_use_autogenerated_schema = 1"

echo "-- generateRandom"
$CLICKHOUSE_CLIENT --query="SELECT count(), toTypeName(any(d)) FROM (SELECT d FROM generateRandom('d Decimal(154, 2)', 1) LIMIT 5)"

rm -f "${USER_FILES_PATH:?}/${F}".*
